import sys


def main():
    data = sys.stdin.buffer.read().split(b'\n')
    sums = {}
    for line in data[1:]:
        p = line.split(b',')
        if len(p) < 3:
            continue
        v = p[2].strip()
        if not v:
            continue
        cat = p[1]
        try:
            sums[cat] += round(float(v) * 100)
        except KeyError:
            sums[cat] = round(float(v) * 100)
    out = []
    for cat in sorted(sums):
        t = sums[cat]
        sign = '-' if t < 0 else ''
        t = abs(t)
        out.append('%s,%s%d.%02d' % (cat.decode(), sign, t // 100, t % 100))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))


main()
